/* JavaScript Node ACM模式 控制台输入获取 */
const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

const lines = [];
let n;
rl.on("line", (line) => {
  lines.push(line);

  if (lines.length === 1) {
    n = lines[0] - 0;
  }

  if (n && lines.length === n + 1) {
    lines.shift();

    lines
      .map((line) => {
        const arr = line.split(" ");
        return {
          name: arr[0],
          gold: arr[1] - 0,
          silver: arr[2] - 0,
          bronze: arr[3] - 0,
        };
      })
      .sort((a, b) => {
        return b.gold !== a.gold
          ? b.gold - a.gold
          : b.silver !== a.silver
          ? b.silver - a.silver
          : b.bronze !== a.bronze
          ? b.bronze - a.bronze
          : a.name == b.name
          ? 0
          : a.name > b.name
          ? 1
          : -1;
      })
      .forEach((country) => {
        console.log(country.name);
      });

    lines.length = 0;
  }
});

