import java.util.Arrays;
import java.util.Scanner;

public class Main {
  // 输入获取
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);

    int n = sc.nextInt();

    Country[] countries = new Country[n];
    for (int i = 0; i < n; i++) {
      Country c = new Country(sc.next(), sc.nextInt(), sc.nextInt(), sc.nextInt());
      countries[i] = c;
    }

    getResult(countries);
  }

  // 算法入口
  public static void getResult(Country[] countries) {
    Arrays.sort(
        countries,
        (a, b) ->
            b.gold != a.gold
                ? b.gold - a.gold
                : b.silver != a.silver
                    ? b.silver - a.silver
                    : b.bronze != a.bronze ? b.bronze - a.bronze : a.name.compareTo(b.name));

    for (Country country : countries) {
      System.out.println(country.name);
    }
  }
}

class Country {
  String name;
  int gold;
  int silver;
  int bronze;

  public Country(String name, int gold, int silver, int bronze) {
    this.name = name;
    this.gold = gold;
    this.silver = silver;
    this.bronze = bronze;
  }
}

